<?php
namespace App\Tests\Runtime;use App\Runtime\{RuntimeApiEntityActionService,RuntimeExternalJsonClient,RuntimeTransactionService,RuntimeHttpException};use PHPUnit\Framework\TestCase;require_once __DIR__.'/RuntimePurchaseItemAuditTest.php';
final class RuntimePurchaseItemQueryTest extends TestCase {
 private function invoke(array $body,array $payload,array &$sent):array{$d=RuntimePurchaseItemAuditTest::definition();foreach(RuntimePurchaseItemAuditTest::data()as $name=>$v)$d['fields'][$name]=['code'=>$name,'jsonPath'=>$name,'dataType'=>is_int($v)?'integer':'string','collection'=>null];$d['apiSource']+=['authHeaders'=>[],'listEndpoint'=>RuntimePurchaseItemAuditTest::endpoint('read')];$rc=new \ReflectionClass(RuntimeApiEntityActionService::class);$s=$rc->newInstanceWithoutConstructor();$client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($u,$m,$h,$r)use(&$sent,$body){$sent[]=$r;return ['status'=>200,'body'=>$body];});$rc->getProperty('externalJsonClient')->setValue($s,$client);$rc->getProperty('transactions')->setValue($s,$this->createStub(RuntimeTransactionService::class));return $rc->getMethod('read')->invoke($s,$d,$payload);}
 public function testNativePagingPreservesAllFiftyFieldsWithoutReapplyingSkip():void{$sent=[];$out=$this->invoke(['success'=>true,'data'=>[RuntimePurchaseItemAuditTest::data()],'total'=>41],['context'=>['proc_compra_id'=>17],'skip'=>40,'take'=>20],$sent);self::assertSame(41,$out['total']);self::assertCount(50,$out['data'][0]);self::assertSame(['resource'=>'proc_compra_itens','operation'=>'read','skip'=>40,'take'=>20,'proc_compra_id'=>17],$sent[0]);}
 public function testMissingContextFailsBeforeNetworkAndForeignOrIncompleteRowsNeverEscape():void{foreach(['context','parent','missing','total']as $case){$sent=[];$r=RuntimePurchaseItemAuditTest::data();$p=['context'=>['proc_compra_id'=>17],'take'=>20];if($case==='context')unset($p['context']);if($case==='parent')$r['proc_compra_id']=18;if($case==='missing')unset($r['calc_gm']);try{$this->invoke(['success'=>true,'data'=>[$r],'total'=>$case==='total'?21:1],$p,$sent);self::fail($case);}catch(RuntimeHttpException $e){self::assertContains($e->getStatusCode(),[422,502]);}self::assertCount($case==='context'?0:1,$sent);}}
}
